import pytest
from candidate import remove_vowels

class TestRemoveVowels:
    def test_remove_vowels_empty_string(self):
        assert remove_vowels('') == ''

    def test_remove_vowels_no_vowels(self):
        assert remove_vowels('bcdf') == 'bcdf'

    def test_remove_vowels_all_vowels(self):
        assert remove_vowels('aaaaa') == ''

    def test_remove_vowels_mixed_case(self):
        assert remove_vowels('aaBAA') == 'B'

    def test_remove_vowels_no_vowels_case_sensitive(self):
        assert remove_vowels('zbcd') == 'zbcd'

    def test_remove_vowels_with_spaces(self):
        assert remove_vowels('abc def') == 'bc df'

    def test_remove_vowels_with_numbers(self):
        assert remove_vowels('abc123') == 'bc123'

    def test_remove_vowels_with_special_chars(self):
        assert remove_vowels('abc!def?') == 'bcd!f?'

    def test_remove_vowels_with_accents(self):
        assert remove_vowels('àbcDef') == 'bcDef'
